// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection, ArrayLike } from '@stdlib/types/array';

/**
* Data set instance.
*/
interface DataSet {
	/**
	* Serializes an instance to a JSON object.
	*
	* @returns JSON object
	*/
	toJSON(): object;
}

/**
* Converts a list of nested arrays to "tidy" data sets.
*
* @param arr - list of nested arrays
* @param names - data set names
* @param fields - list of field names
* @returns list of data sets
*
* @example
* var a = [ [ 1, 2 ], [ 3, 4 ] ];
* var b = [ [ 5, 6 ], [ 7, 8 ] ];
*
* var v = nestedarrays2tidy( [ a, b ], [ 'data1', 'data2' ], [ 'x', 'y' ] );
* // returns [ <DataSet>, <DataSet> ]
*/
declare function nestedarrays2tidy( arr: ArrayLike<ArrayLike<Collection<unknown>>>, names: ArrayLike<string>, fields: ArrayLike<string> ): Array<DataSet>;


// EXPORTS //

export = nestedarrays2tidy;
